1	import { createHash, randomUUID } from "node:crypto";
2	import { readFileSync } from "node:fs";
3	import pg from "pg";
4	import { getConfig, loadConfig } from "../config";
5	import { buildSearchText, contentHash, NORMALISER_VERSION } from "../normalise";
6	import { reduceMarkup, SANITISER_VERSION } from "../sanitise/reduce";
7	import { validateArticle } from "../validate/article";
8	import { log } from "../log";
9	
10	export type LoadResult = {
11	  received: number;
12	  admitted: number;
13	  quarantined: number;
14	  duplicate: number;
15	  batchId: string;
16	};
17	
18	export async function loadArticlesFile(
19	  filePath: string,
20	  batchKind: "live" | "backfill" = "backfill",
21	): Promise<LoadResult> {
22	  const raw = JSON.parse(readFileSync(filePath, "utf8")) as unknown;
23	  if (!Array.isArray(raw)) throw new Error("sample file must be a JSON array");
24	  return loadArticles(raw, batchKind);
25	}
