1	/**
2	 * Sample loader CLI. Full ingest pipeline lands in phase 2;
3	 * this stub exits 0 when SEED_SAMPLE is false or the file is missing until then.
4	 */
5	import { existsSync } from "node:fs";
6	import { log } from "../lib/log";
7	
8	async function main(): Promise<void> {
9	  const args = process.argv.slice(2);
10	  let file = "data/sample_articles.json";
11	  let kind = "backfill";
12	  for (let i = 0; i < args.length; i++) {
13	    if (args[i] === "--file" && args[i + 1]) {
14	      file = args[++i]!;
15	    } else if (args[i] === "--kind" && args[i + 1]) {
16	      kind = args[++i]!;
17	    }
18	  }
19	
20	  if (process.env.SEED_SAMPLE === "false") {
21	    log.info("SEED_SAMPLE=false; skip load");
22	    return;
23	  }
24	
25	  if (!existsSync(file)) {
26	    log.warn({ file }, "sample file missing; skip seed until ingest is wired");
27	    return;
28	  }
29	
30	  // Dynamic import so the image builds before phase 2 completes.
31	  try {
32	    const { loadArticlesFile } = await import("../lib/ingest/ingest");
33	    const result = await loadArticlesFile(file, kind === "live" ? "live" : "backfill");
34	    log.info(result, "seed complete");
35	    console.log(
36	      `received ${result.received}, admitted ${result.admitted}, quarantined ${result.quarantined}, duplicate ${result.duplicate}`,
37	    );
38	  } catch (err) {
39	    if (err instanceof Error && err.message.includes("Cannot find module")) {
40	      log.warn("ingest module not ready; skip seed");
41	      return;
42	    }
43	    throw err;
44	  }
45	}
46	
47	main().catch((err) => {
48	  log.error({ err }, "load failed");
49	  process.exit(1);
50	});
51

