  const res = await runLoad({
    rate: opts.rate, durationSec: opts.duration, warmupSec: opts.warmup, concurrency: opts.concurrency,
    work: async () => {
      const { article, planted: brand } = gen.next();
      attempted++;
      if (brand) planted.add(article.id);
      try { await target(article); } catch (e) { rejected++; throw e; }
    },
  });

