  report.metric('sent', res.sent);
  report.metric('achieved rate', res.achievedRate, '/s');
  report.metric('latency p50', s.p50, 'ms'); report.metric('latency p95', s.p95, 'ms'); report.metric('latency p99', s.p99, 'ms');
  conservation(report, attempted, { stored: seen.size, rejected });
