  rate: 800, duration: 20, warmup: 3, concurrency: 8, batch: 20, seed: 42,
  planted: 0.05, redelivery: 0.01, contentDup: 0.02, markup: 0.05, invalid: 0.01,
  samples: 'data/sample_articles.json', keepDb: false,
});

