  const admin = new pg.Client(conn('postgres', adminUser, adminPassword));
  await admin.connect();
  await admin.query(`CREATE DATABASE ${dbName}`);
  const dbAdmin = new pg.Client(conn(dbName, adminUser, adminPassword));
  await dbAdmin.connect();
